    private final class Observer extends CompletableFuture<Void> {
        private final java.util.concurrent.atomic.AtomicInteger claim=new java.util.concurrent.atomic.AtomicInteger();
        boolean external(){return claim.get()==3;}
        @Override public boolean cancel(boolean interrupt){return claim.compareAndSet(0,1) && super.cancel(interrupt);}
        @Override public boolean complete(Void result){return claim.compareAndSet(0,3) && super.complete(result);}
        @Override public boolean completeExceptionally(Throwable failure){return claim.compareAndSet(0,3) && super.completeExceptionally(failure);}
        void deliver(Job original,Throwable failure){if(!claim.compareAndSet(0,2))return;if(failure==null)super.complete(null);else super.completeExceptionally(failure);}
    }
